function debounce(fn, ms) {
  return (...args) => {
    let id;
    clearTimeout(id);
    id = setTimeout(() => fn(...args), ms);
  };
}
const log = debounce(x => console.log(x), 100);
log('a'); log('b'); log('c');
```

